package org.xingmu.tv;
import android.content.Context;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
final class SourceRepository {
 private final Context context;SourceRepository(Context c){context=c.getApplicationContext();}
 private File file(){return new File(context.getFilesDir(),"tvbox-data.json");}
 TvBoxConfig load()throws IOException{TvBoxConfig result=TvBoxConfig.parse(CatalogRepository.read(context.getAssets().open("lightconer-tvbox.json")),null);if(file().exists()){TvBoxConfig custom=TvBoxConfig.parse(CatalogRepository.read(new FileInputStream(file())),null);Set<String> apis=new HashSet<>();for(TvBoxConfig.Site site:result.sites)apis.add(site.api);for(TvBoxConfig.Site site:custom.sites)if(apis.add(site.api))result.sites.add(site);for(String url:custom.liveUrls)if(!result.liveUrls.contains(url))result.liveUrls.add(url);result.inline.addAll(custom.inline);result.issues.addAll(custom.issues);result.unsupported+=custom.unsupported;}return result;}
 int save(String text,String base)throws IOException{synchronized(SourceRepository.class){TvBoxConfig incoming=TvBoxConfig.parse(text,base),config=incoming;int added=incoming.sites.size()+incoming.liveUrls.size()+incoming.inline.size();if(file().exists()){TvBoxConfig old=TvBoxConfig.parse(CatalogRepository.read(new FileInputStream(file())),null);Set<String> apis=new HashSet<>();for(TvBoxConfig.Site site:config.sites)apis.add(site.api);for(TvBoxConfig.Site site:old.sites)if(apis.add(site.api))config.sites.add(site);for(String url:old.liveUrls)if(!config.liveUrls.contains(url))config.liveUrls.add(url);}if(config.sites.size()>50||config.liveUrls.size()>30)throw new IOException("最多保留 50 个自定义影视接口和 30 个直播订阅");try{JSONObject data=new JSONObject();JSONArray sites=new JSONArray(),lives=new JSONArray();for(TvBoxConfig.Site s:config.sites)sites.put(new JSONObject().put("key",s.key).put("name",s.name).put("type",1).put("api",s.api));for(String url:config.liveUrls)lives.put(new JSONObject().put("url",url));data.put("sites",sites).put("lives",lives);File temp=new File(context.getFilesDir(),"tvbox-data.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(data.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!temp.renameTo(file()))throw new IOException("配置保存失败");if(!config.inline.isEmpty()){JSONArray items=new JSONArray();for(JSONObject item:config.inline)items.put(item);new CatalogRepository(context).merge(new JSONObject().put("authorized",true).put("items",items).toString(),"domestic","未分类");}String result="标准影视 API "+config.sites.size()+" 个，直播列表 "+config.liveUrls.size()+" 个，直接频道 "+config.inline.size()+" 个；插件站点 "+config.unsupported+" 个未加载";if(!config.issues.isEmpty())result+="，另有 "+config.issues.size()+" 项地址不支持";context.getSharedPreferences("sources",0).edit().putString("report",result).apply();return added;}catch(JSONException e){throw new IOException("配置保存失败",e);}}}
 String addRemote(String text)throws IOException{String[] rows=text.trim().split("\r?\n");if(rows.length>30)throw new IOException("每次最多导入 30 个地址");int success=0,failed=0;for(String row:rows){String url=row.trim();if(url.isEmpty())continue;try{String content=PublicHttp.get(url);if(TvBoxConfig.recognises(content))save(content,url);else{VodApi.parse(content);JSONObject site=new JSONObject().put("key","custom_"+Integer.toHexString(url.hashCode())).put("name",new java.net.URL(url).getHost()).put("type",1).put("api",url);save(new JSONObject().put("sites",new JSONArray().put(site)).toString(),url);}success++;}catch(Exception e){failed++;}}return "来源导入：成功 "+success+" 个，失败或不兼容 "+failed+" 个。影视页顶部可切换。";}
 String report(){return context.getSharedPreferences("sources",0).getString("report","已内置 Lightconer 聚合源；支持叠加自定义配置");}
 void clear(){file().delete();context.getSharedPreferences("sources",0).edit().remove("report").apply();}
}
